//! Harness: the loop -- the model's first connection to the real world.
//!
//! The entire secret of an AI coding agent in one pattern:
//!
//!     while stop_reason == "tool_use":
//!         response = LLM(messages, tools)
//!         execute tools
//!         append results

use anyhow::Result;
use harness::{ AnthropicClient, Config, ContentBlock, ToolDef, assistant_message,
    tool_result_message, user_text};
use std::io::{self, Write};

fn bash_tool() -> ToolDef {
    ToolDef {
        name: "bash".to_string(),
        description: "Run a shell command.".to_string(),
        input_schema: serde_json::json!({
            "type": "object",
            "properties": {"command": {"type": "string"}},
            "required": ["command"]
        }),
    }
}

async fn agent_loop(
    client: &AnthropicClient,
    messages: &mut Vec<serde_json::Value>,
    workdir: &std::path::Path,
) {
    let system = format!("You are a coding agent at {}. Use bash to solve tasks. Act, don't explain.", workdir.display());
    let tools = vec![bash_tool()];

    loop {
        let resp = match client.create_message(&system, messages, &tools, 8000).await {
            Ok(r) => r,
            Err(e) => {
                eprintln!("API error: {e}");
                return;
            }
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        messages.push(assistant_message(&resp.content));
        if stop {
            return;
        }
        let mut results = Vec::new();
        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = if name == "bash" {
                    let cmd = input["command"].as_str().unwrap_or("");
                    println!("\x1b[33m$ {cmd}\x1b[0m");
                    harness::tools::run_bash(cmd, workdir)
                } else {
                    format!("Unknown tool: {name}")
                };
                println!("{}", &output[..output.len().min(200)]);
                results.push(ContentBlock::ToolResult {
                    tool_use_id: id.clone(),
                    content: output,
                });
            }
        }
        messages.push(tool_result_message(results));
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::load()?;
    let client = AnthropicClient::new(&config.api_key, &config.base_url, &config.model_id);
    let workdir = config.workdir.clone();
    let mut history: Vec<serde_json::Value> = Vec::new();

    loop {
        print!("\x1b[36ms01 >> \x1b[0m");
        io::stdout().flush()?;
        let mut query = String::new();
        match io::stdin().read_line(&mut query) {
            Ok(0) | Err(_) => break,
            _ => {}
        }
        let query = query.trim();
        if query.is_empty() || query == "q" || query == "exit" {
            break;
        }
        history.push(user_text(query));
        agent_loop(&client, &mut history, &workdir).await;

        // Print final text response
        if let Some(last) = history.last() {
            if let Some(content) = last["content"].as_array() {
                for block in content {
                    if let Some(text) = block["text"].as_str() {
                        println!("{text}");
                    }
                }
            } else if let Some(text) = last["content"].as_str() {
                println!("{text}");
            }
        }
        println!();
    }
    Ok(())
}

//! Harness: tool dispatch -- expanding what the model can reach.
//!
//! The agent loop from s01 didn't change. We just added tools to the array
//! and a dispatch map to route calls.

use anyhow::Result;
use harness::{AnthropicClient, Config, ContentBlock,
    assistant_message, tool_result_message, user_text, base_tools};
use std::io::{self, Write};

fn dispatch_tool(name: &str, input: &serde_json::Value, workdir: &std::path::Path) -> String {
    match name {
        "bash" => harness::tools::run_bash(input["command"].as_str().unwrap_or(""), workdir),
        "read_file" => harness::tools::run_read(input["path"].as_str().unwrap_or(""), workdir, input["limit"].as_u64().map(|l| l as usize)),
        "write_file" => harness::tools::run_write(input["path"].as_str().unwrap_or(""), workdir, input["content"].as_str().unwrap_or("")),
        "edit_file" => harness::tools::run_edit(input["path"].as_str().unwrap_or(""), workdir, input["old_text"].as_str().unwrap_or(""), input["new_text"].as_str().unwrap_or("")),
        _ => format!("Unknown tool: {name}"),
    }
}

async fn agent_loop(
    client: &AnthropicClient,
    messages: &mut Vec<serde_json::Value>,
    workdir: &std::path::Path,
) {
    let system = format!("You are a coding agent at {}. Use tools to solve tasks. Act, don't explain.", workdir.display());
    let tools = base_tools();

    loop {
        let resp = match client.create_message(&system, messages, &tools, 8000).await {
            Ok(r) => r,
            Err(e) => { eprintln!("API error: {e}"); return; }
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        messages.push(assistant_message(&resp.content));
        if stop { return; }

        let mut results = Vec::new();
        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = dispatch_tool(name, input, workdir);
                println!("> {name}:");
                println!("{}", &output[..output.len().min(200)]);
                results.push(ContentBlock::ToolResult { tool_use_id: id.clone(), content: output });
            }
        }
        messages.push(tool_result_message(results));
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::load()?;
    let client = AnthropicClient::new(&config.api_key, &config.base_url, &config.model_id);
    let workdir = config.workdir.clone();
    let mut history: Vec<serde_json::Value> = Vec::new();

    loop {
        print!("\x1b[36ms02 >> \x1b[0m");
        io::stdout().flush()?;
        let mut query = String::new();
        match io::stdin().read_line(&mut query) { Ok(0) | Err(_) => break, _ => {} }
        let query = query.trim();
        if query.is_empty() || query == "q" || query == "exit" { break; }
        history.push(user_text(query));
        agent_loop(&client, &mut history, &workdir).await;

        if let Some(last) = history.last() {
            if let Some(content) = last["content"].as_array() {
                for block in content {
                    if let Some(text) = block["text"].as_str() { println!("{text}"); }
                }
            } else if let Some(text) = last["content"].as_str() { println!("{text}"); }
        }
        println!();
    }
    Ok(())
}

//! Harness: planning -- keeping the model on course without scripting the route.
//!
//! The model tracks its own progress via a TodoManager. A nag reminder
//! forces it to keep updating when it forgets.

use anyhow::Result;
use harness::{AnthropicClient, Config, ContentBlock, ToolDef, TodoManager,
    assistant_message, tool_result_message, user_text, base_tools};
use std::io::{self, Write};
use std::sync::Mutex;

fn todo_tool() -> ToolDef {
    ToolDef {
        name: "todo".to_string(),
        description: "Update task list. Track progress on multi-step tasks.".to_string(),
        input_schema: serde_json::json!({
            "type": "object",
            "properties": {
                "items": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "properties": {
                            "id": {"type": "string"},
                            "text": {"type": "string"},
                            "status": {"type": "string", "enum": ["pending", "in_progress", "completed"]}
                        },
                        "required": ["id", "text", "status"]
                    }
                }
            },
            "required": ["items"]
        }),
    }
}

async fn agent_loop(
    client: &AnthropicClient,
    messages: &mut Vec<serde_json::Value>,
    workdir: &std::path::Path,
    todo: &Mutex<TodoManager>,
) {
    let system = format!(
        "You are a coding agent at {}.\nUse the todo tool to plan multi-step tasks. \
         Mark in_progress before starting, completed when done.\nPrefer tools over prose.",
        workdir.display()
    );
    let mut tools = base_tools();
    tools.push(todo_tool());

    let mut rounds_since_todo: usize = 0;

    loop {
        let resp = match client.create_message(&system, messages, &tools, 8000).await {
            Ok(r) => r,
            Err(e) => { eprintln!("API error: {e}"); return; }
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        messages.push(assistant_message(&resp.content));
        if stop { return; }

        let mut results = Vec::new();
        let mut used_todo = false;

        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = match name.as_str() {
                    "bash" => harness::tools::run_bash(input["command"].as_str().unwrap_or(""), workdir),
                    "read_file" => harness::tools::run_read(input["path"].as_str().unwrap_or(""), workdir, input["limit"].as_u64().map(|l| l as usize)),
                    "write_file" => harness::tools::run_write(input["path"].as_str().unwrap_or(""), workdir, input["content"].as_str().unwrap_or("")),
                    "edit_file" => harness::tools::run_edit(input["path"].as_str().unwrap_or(""), workdir, input["old_text"].as_str().unwrap_or(""), input["new_text"].as_str().unwrap_or("")),
                    "todo" => {
                        used_todo = true;
                        let items = input["items"].as_array().cloned().unwrap_or_default();
                        let mut todo = todo.lock().unwrap();
                        todo.update(items).unwrap_or_else(|e| format!("Error: {e}"))
                    }
                    _ => format!("Unknown tool: {name}"),
                };
                println!("> {name}:");
                println!("{}", &output[..output.len().min(200)]);
                results.push(ContentBlock::ToolResult {
                    tool_use_id: id.clone(),
                    content: output,
                });
            }
        }

        rounds_since_todo = if used_todo { 0 } else { rounds_since_todo + 1 };
        if rounds_since_todo >= 3 {
            results.push(ContentBlock::Text {
                text: "<reminder>Update your todos.</reminder>".to_string(),
            });
        }

        messages.push(tool_result_message(results));
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::load()?;
    let client = AnthropicClient::new(&config.api_key, &config.base_url, &config.model_id);
    let workdir = config.workdir.clone();
    let todo = Mutex::new(TodoManager::new());
    let mut history: Vec<serde_json::Value> = Vec::new();

    loop {
        print!("\x1b[36ms03 >> \x1b[0m");
        io::stdout().flush()?;
        let mut query = String::new();
        match io::stdin().read_line(&mut query) {
            Ok(0) | Err(_) => break,
            _ => {}
        }
        let query = query.trim();
        if query.is_empty() || query == "q" || query == "exit" { break; }
        history.push(user_text(query));
        agent_loop(&client, &mut history, &workdir, &todo).await;

        if let Some(last) = history.last() {
            if let Some(content) = last["content"].as_array() {
                for block in content {
                    if let Some(text) = block["text"].as_str() { println!("{text}"); }
                }
            } else if let Some(text) = last["content"].as_str() { println!("{text}"); }
        }
        println!();
    }
    Ok(())
}

//! Harness: context isolation -- protecting the model's clarity of thought.
//!
//! Spawn a child agent with fresh messages=[]. The child works in its own
//! context, sharing the filesystem, then returns only a summary to the parent.

use anyhow::Result;
use harness::{AnthropicClient, Config, ContentBlock, ToolDef,
    assistant_message, tool_result_message, user_text, base_tools, extract_text};
use std::io::{self, Write};
use std::path::Path;

fn task_tool() -> ToolDef {
    ToolDef {
        name: "task".to_string(),
        description: "Spawn a subagent with fresh context. It shares the filesystem but not conversation history.".to_string(),
        input_schema: serde_json::json!({
            "type": "object",
            "properties": {"prompt": {"type": "string"}, "description": {"type": "string"}},
            "required": ["prompt"]
        }),
    }
}

async fn run_subagent(client: &AnthropicClient, prompt: &str, workdir: &Path) -> String {
    let sub_tools = base_tools();
    let mut sub_msgs = vec![user_text(prompt)];
    let mut last_resp = None;

    for _ in 0..30 {
        let resp = match client.create_message(
            "You are a coding subagent. Complete the task and summarize your findings.",
            &sub_msgs, &sub_tools, 8000,
        ).await {
            Ok(r) => r,
            Err(_) => break,
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        sub_msgs.push(assistant_message(&resp.content));
        last_resp = Some(resp.clone());
        if stop { break; }

        let mut results: Vec<ContentBlock> = Vec::new();
        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = match &**name {
                    "bash" => harness::tools::run_bash(input["command"].as_str().unwrap_or(""), workdir),
                    "read_file" => harness::tools::run_read(input["path"].as_str().unwrap_or(""), workdir, input["limit"].as_u64().map(|l| l as usize)),
                    "write_file" => harness::tools::run_write(input["path"].as_str().unwrap_or(""), workdir, input["content"].as_str().unwrap_or("")),
                    "edit_file" => harness::tools::run_edit(input["path"].as_str().unwrap_or(""), workdir, input["old_text"].as_str().unwrap_or(""), input["new_text"].as_str().unwrap_or("")),
                    _ => format!("Unknown tool: {name}"),
                };
                results.push(ContentBlock::ToolResult { tool_use_id: id.clone(), content: output });
            }
        }
        if !results.is_empty() {
            sub_msgs.push(tool_result_message(results));
        }
    }

    if let Some(r) = &last_resp {
        let text = extract_text(&r.content);
        if text.is_empty() { "(no summary)".to_string() } else { text }
    } else {
        "(subagent failed)".to_string()
    }
}

async fn agent_loop(
    client: &AnthropicClient,
    messages: &mut Vec<serde_json::Value>,
    workdir: &Path,
) {
    let system = format!("You are a coding agent at {}. Use the task tool to delegate exploration or subtasks.", workdir.display());
    let mut tools = base_tools();
    tools.push(task_tool());

    loop {
        let resp = match client.create_message(&system, messages, &tools, 8000).await {
            Ok(r) => r,
            Err(e) => { eprintln!("API error: {e}"); return; }
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        messages.push(assistant_message(&resp.content));
        if stop { return; }

        let mut results: Vec<ContentBlock> = Vec::new();
        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = if name == "task" {
                    let desc = input["description"].as_str().unwrap_or("subtask");
                    let prompt = input["prompt"].as_str().unwrap_or("");
                    println!("> task ({desc}): {}", &prompt[..prompt.len().min(80)]);
                    run_subagent(client, prompt, workdir).await
                } else {
                    match &**name {
                        "bash" => harness::tools::run_bash(input["command"].as_str().unwrap_or(""), workdir),
                        "read_file" => harness::tools::run_read(input["path"].as_str().unwrap_or(""), workdir, input["limit"].as_u64().map(|l| l as usize)),
                        "write_file" => harness::tools::run_write(input["path"].as_str().unwrap_or(""), workdir, input["content"].as_str().unwrap_or("")),
                        "edit_file" => harness::tools::run_edit(input["path"].as_str().unwrap_or(""), workdir, input["old_text"].as_str().unwrap_or(""), input["new_text"].as_str().unwrap_or("")),
                        _ => format!("Unknown tool: {name}"),
                    }
                };
                println!("  {}", &output[..output.len().min(200)]);
                results.push(ContentBlock::ToolResult { tool_use_id: id.clone(), content: output });
            }
        }
        messages.push(tool_result_message(results));
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::load()?;
    let client = AnthropicClient::new(&config.api_key, &config.base_url, &config.model_id);
    let workdir = config.workdir.clone();
    let mut history: Vec<serde_json::Value> = Vec::new();

    loop {
        print!("\x1b[36ms04 >> \x1b[0m");
        io::stdout().flush()?;
        let mut query = String::new();
        match io::stdin().read_line(&mut query) { Ok(0) | Err(_) => break, _ => {} }
        let query = query.trim();
        if query.is_empty() || query == "q" || query == "exit" { break; }
        history.push(user_text(query));
        agent_loop(&client, &mut history, &workdir).await;

        if let Some(last) = history.last() {
            if let Some(content) = last["content"].as_array() {
                for block in content {
                    if let Some(text) = block["text"].as_str() { println!("{text}"); }
                }
            } else if let Some(text) = last["content"].as_str() { println!("{text}"); }
        }
        println!();
    }
    Ok(())
}

//! Harness: on-demand knowledge -- domain expertise, loaded when the model asks.
//!
//! Two-layer skill injection: Layer 1 = skill names in system prompt,
//! Layer 2 = full skill body returned in tool_result on demand.

use anyhow::Result;
use harness::{AnthropicClient, Config, ContentBlock, ToolDef, SkillLoader,
    assistant_message, tool_result_message, user_text, base_tools};
use std::io::{self, Write};

fn load_skill_tool() -> ToolDef {
    ToolDef {
        name: "load_skill".to_string(),
        description: "Load specialized knowledge by name.".to_string(),
        input_schema: serde_json::json!({
            "type": "object",
            "properties": {"name": {"type": "string", "description": "Skill name to load"}},
            "required": ["name"]
        }),
    }
}

async fn agent_loop(
    client: &AnthropicClient,
    messages: &mut Vec<serde_json::Value>,
    workdir: &std::path::Path,
    skills: &SkillLoader,
) {
    let system = format!(
        "You are a coding agent at {}.\nUse load_skill to access specialized knowledge before tackling unfamiliar topics.\n\nSkills available:\n{}",
        workdir.display(),
        skills.get_descriptions()
    );
    let mut tools = base_tools();
    tools.push(load_skill_tool());

    loop {
        let resp = match client.create_message(&system, messages, &tools, 8000).await {
            Ok(r) => r,
            Err(e) => { eprintln!("API error: {e}"); return; }
        };
        let stop = resp.stop_reason.as_deref() != Some("tool_use");
        messages.push(assistant_message(&resp.content));
        if stop { return; }

        let mut results = Vec::new();
        for block in &resp.content {
            if let ContentBlock::ToolUse { id, name, input } = block {
                let output = match name.as_str() {
                    "bash" => harness::tools::run_bash(input["command"].as_str().unwrap_or(""), workdir),
                    "read_file" => harness::tools::run_read(input["path"].as_str().unwrap_or(""), workdir, input["limit"].as_u64().map(|l| l as usize)),
                    "write_file" => harness::tools::run_write(input["path"].as_str().unwrap_or(""), workdir, input["content"].as_str().unwrap_or("")),
                    "edit_file" => harness::tools::run_edit(input["path"].as_str().unwrap_or(""), workdir, input["old_text"].as_str().unwrap_or(""), input["new_text"].as_str().unwrap_or("")),
                    "load_skill" => skills.get_content(input["name"].as_str().unwrap_or("")),
                    _ => format!("Unknown tool: {name}"),
                };
                println!("> {name}:");
                println!("{}", &output[..output.len().min(200)]);
                results.push(ContentBlock::ToolResult {
                    tool_use_id: id.clone(),
                    content: output,
                });
            }
        }
        messages.push(tool_result_message(results));
    }
}

#[tokio::main]
async fn main() -> Result<()> {
    let config = Config::load()?;
    let client = AnthropicClient::new(&config.api_key, &config.base_url, &config.model_id);
    let workdir = config.workdir.clone();
    let skills = SkillLoader::new(&workdir.join("skills"));
    let mut history: Vec<serde_json::Value> = Vec::new();

    loop {
        print!("\x1b[36ms05 >> \x1b[0m");
        io::stdout().flush()?;
        let mut query = String::new();
        match io::stdin().read_line(&mut query) {
            Ok(0) | Err(_) => break,
            _ => {}
        }
        let query = query.trim();
        if query.is_empty() || query == "q" || query == "exit" { break; }
        history.push(user_text(query));
        agent_loop(&client, &mut history, &workdir, &skills).await;

        if let Some(last) = history.last() {
            if let Some(content) = last["content"].as_array() {
                for block in content {
                    if let Some(text) = block["text"].as_str() { println!("{text}"); }
